package com.bank.ops;

import java.util.*;
import java.util.logging.*;

public class MinWindowDemo {
    private static final Logger log = Logger.getLogger(MinWindowDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        IncidentLogAnalyzer analyzer = new IncidentLogAnalyzer();

        String log1 = "ADOBECODEBANC";
        String required = "ABC";
        String window = analyzer.minCoveringWindow(log1, required);
        log.info(() -> "Shortest covering window: '" + window + "'");
    }
}

