class IncidentLogAnalyzer {
    private static final Logger log = Logger.getLogger(IncidentLogAnalyzer.class.getName());

    // Expand/shrink with need map + matched count. O(n) time.
    String minCoveringWindow(String s, String pattern) {
        if (s.isEmpty() || pattern.isEmpty()) return "";
        Map<Character, Integer> need = new HashMap<>();
        for (char c : pattern.toCharArray()) need.merge(c, 1, Integer::sum);
        int required = need.size();

        Map<Character, Integer> window = new HashMap<>();
        int formed = 0, left = 0;
        int bestLen = Integer.MAX_VALUE, bestStart = 0;

        for (int right = 0; right < s.length(); right++) {
            char rc = s.charAt(right);
            window.merge(rc, 1, Integer::sum);                 // expand
            if (need.containsKey(rc) && window.get(rc).intValue() == need.get(rc).intValue()) {
                formed++;
            }
            while (formed == required) {                        // valid → try shrink
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                }
                char lc = s.charAt(left);
                window.merge(lc, -1, Integer::sum);
                if (need.containsKey(lc) && window.get(lc) < need.get(lc)) {
                    formed--;                                  // dropped below requirement
                }
                left++;
            }
        }
        if (bestLen == Integer.MAX_VALUE) {
            log.warning("No covering window found");
            return "";
        }
        return s.substring(bestStart, bestStart + bestLen);
    }
}

